#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b;}#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1const int N = 1e6 + 10;int n,dp[N],bac[N];signed main(){	ios::sync_with_stdio(false);	cin.tie(nullptr);cout.tie(nullptr);	cin >> n;	for(int i=1;i<=n;i++){		int a,b;cin >> a >> b;		bac[a] = b;	}	int rem = -1;	if(bac[0])dp[0] = 1;	for(int i=1;i<N;i++){		if(!bac[i]){			dp[i] = dp[i - 1];		}else{			if(bac[i] >= i){				dp[i] = 1;			}else{				dp[i] = dp[i - bac[i] - 1] + 1;			}		}		rem = max(rem,dp[i]);	}	cout << n - rem << '\n';	return 0;}